const staticData = $getWorkflowStaticData('global');
const reviewGate = staticData.reviewGate || {};
reviewGate.pendingByReviewExecutionProcessId ??= {};
reviewGate.pendingBySourceExecutionId ??= {};
reviewGate.completedBySourceExecutionId ??= {};
staticData.reviewGate = reviewGate;

return $input.all().flatMap((item) => {
  const task = item.json.task;
  const workspace = item.json.latest_workspace;
  const latestCodingExecution = item.json.latest_coding_execution;

  if (!task?.id || !workspace?.id || !latestCodingExecution?.id) {
    return [];
  }

  if (item.json.queue_state?.merge_queue?.id) {
    return [];
  }

  if (reviewGate.pendingBySourceExecutionId[latestCodingExecution.id]) {
    return [];
  }

  if (reviewGate.completedBySourceExecutionId[latestCodingExecution.id]) {
    return [];
  }

  if (item.json.latest_review_attention?.execution_process_id === latestCodingExecution.id) {
    return [];
  }

  return [{
    json: {
      projectId: task.project_id,
      taskId: task.id,
      taskTitle: task.title,
      taskDescription: task.description || '',
      workspaceId: workspace.id,
      worktreePath: workspace.agent_working_dir || '',
      worktreeBranch: workspace.branch || '',
      sourceExecutionProcessId: latestCodingExecution.id,
    },
  }];
});

const staticData = $getWorkflowStaticData('global');
const reviewGate = staticData.reviewGate || {};
reviewGate.pendingByReviewExecutionProcessId ??= {};
reviewGate.pendingBySourceExecutionId ??= {};
reviewGate.completedBySourceExecutionId ??= {};
staticData.reviewGate = reviewGate;

if (!$json.reviewExecutionProcessId || !$json.sourceExecutionProcessId) {
  throw new Error('Missing review execution registration identifiers');
}

reviewGate.pendingByReviewExecutionProcessId[$json.reviewExecutionProcessId] = {
  conversationId: $json.conversationId,
  projectId: $json.projectId,
  taskId: $json.taskId,
  workspaceId: $json.workspaceId,
  sourceExecutionProcessId: $json.sourceExecutionProcessId,
  repoIdsJson: $json.repoIdsJson,
  createdAt: new Date().toISOString(),
};
reviewGate.pendingBySourceExecutionId[$json.sourceExecutionProcessId] = $json.reviewExecutionProcessId;

return { json: $json };
